import {
  appendBlockChildren,
  createDatabasePage,
  deleteBlock,
  queryDatabase,
  retrieveBlockChildren,
  updatePageProperties,
} from './notion.mjs';

const MAX_RICH_TEXT_CHUNK = 1900;
const MAX_RICH_TEXT_ITEMS = 100;
const MAX_PAYLOAD_LENGTH = MAX_RICH_TEXT_CHUNK * MAX_RICH_TEXT_ITEMS;
// The packet now carries a compact active-spec catalog so the remote agent can
// return one integrated briefing per dashboard spec. Keep a bounded budget well
// below Notion's block capacity while allowing the current project set to fit.
const REMOTE_READABLE_LIMIT = 50_000;
const BODY_MARKER = 'MOLIP_AGENT_INPUT_V1';

function textObjects(value, maxItems = MAX_RICH_TEXT_ITEMS) {
  const text = String(value || '');
  const parts = [];
  for (let index = 0; index < text.length && parts.length < maxItems; index += MAX_RICH_TEXT_CHUNK) {
    parts.push({ type: 'text', text: { content: text.slice(index, index + MAX_RICH_TEXT_CHUNK) } });
  }
  return parts;
}

function title(value) {
  return { title: textObjects(value, 1) };
}

function richText(value) {
  return { rich_text: textObjects(value) };
}

function date(value) {
  return { date: value ? { start: value } : null };
}

function inputRunId(packet) {
  return `rule-input:${packet.runId}`;
}

function packetDate(packet) {
  return packet.runId.slice(0, 10);
}

function propertiesFor(packet) {
  const packetSize = remotePacketSize(packet);
  return {
    이름: title(`규칙 입력 / ${packetDate(packet)}`),
    프로젝트명: richText('규칙 입력'),
    기준일: date(packetDate(packet)),
    run_id: richText(inputRunId(packet)),
    '현재 진행 요약': richText('대시보드 규칙 엔진이 게시한 에이전트용 정량 사실 스냅샷'),
    payload: richText(JSON.stringify({
      storage: 'page_code_block',
      format: 'json',
      marker: BODY_MARKER,
      runId: packet.runId,
      bytes: packetSize,
    })),
  };
}

function packetBlock(packet) {
  return {
    object: 'block',
    type: 'code',
    code: {
      rich_text: textObjects(JSON.stringify(packet)),
      language: 'json',
      caption: textObjects(BODY_MARKER, 1),
    },
  };
}

function blockCaption(block) {
  return (block?.code?.caption || []).map(item => item.plain_text || item.text?.content || '').join('');
}

function isManagedPacketBlock(block) {
  return block?.type === 'code' && blockCaption(block) === BODY_MARKER;
}

export async function publishAgentInputToNotion({
  databaseId,
  packet,
  query = queryDatabase,
  create = createDatabasePage,
  update = updatePageProperties,
  listChildren = retrieveBlockChildren,
  append = appendBlockChildren,
  remove = deleteBlock,
}) {
  const payloadLength = remotePacketSize(packet);
  if (payloadLength > MAX_PAYLOAD_LENGTH) throw new Error(`원격 규칙 입력이 Notion payload 한도(${MAX_PAYLOAD_LENGTH}자)를 초과했습니다: ${payloadLength}자`);
  if (payloadLength > REMOTE_READABLE_LIMIT) throw new Error(`원격 규칙 입력이 원격 조회 안전 한도(${REMOTE_READABLE_LIMIT}자)를 초과했습니다: ${payloadLength}자`);
  const runId = inputRunId(packet);
  const rows = await query(databaseId, { property: 'run_id', rich_text: { equals: runId } });
  const properties = propertiesFor(packet);
  if (rows[0]) {
    const existingBlocks = await listChildren(rows[0].id);
    await append(rows[0].id, [packetBlock(packet)]);
    for (const block of existingBlocks.filter(isManagedPacketBlock)) await remove(block.id);
    await update(rows[0].id, properties);
    return { status: 'updated', pageId: rows[0].id, runId, date: packetDate(packet), bytes: payloadLength };
  }
  const page = await create(databaseId, properties, [packetBlock(packet)]);
  return { status: 'created', pageId: page.id, runId, date: packetDate(packet), bytes: payloadLength };
}

export function remotePacketSize(packet) {
  return JSON.stringify(packet).length;
}

export const AGENT_INPUT_REMOTE_READABLE_LIMIT = REMOTE_READABLE_LIMIT;

import { queryDatabase, searchDatabases, flatten, dbTitle, retrieveBlockChildren, retrieveComments } from './notion.mjs';
import { ignoredNotionUserIds, removeIgnoredAssignees } from './notion-users.mjs';
import { inspectWorkDatabaseSetup } from './notion-setup.mjs';
import { excludeUncollectedHierarchy, resolveTaskProjects, selectProjectTasks } from './task-hierarchy.mjs';

const norm = value => String(value || '').replace(/\s+/g, '').toLowerCase();
const pick = (row, names) => names.find(name => row[name] !== undefined && row[name] !== null) !== undefined
  ? row[names.find(name => row[name] !== undefined && row[name] !== null)] : null;
const dateStart = value => value?.start || value || null;
const list = value => Array.isArray(value) ? value : String(value || '').split(',').map(item => item.trim()).filter(Boolean);
const single = value => Array.isArray(value) ? value[0] || null : value;
const userList = value => Array.isArray(value) ? value.filter(user => user?.id) : [];

function blockText(block) {
  const content = block?.[block.type];
  if (Array.isArray(content?.cells)) {
    return content.cells.map(cell => (cell || []).map(text => text.plain_text || '').join('')).join(' | ');
  }
  return (content?.rich_text || []).map(text => text.plain_text || '').join('');
}

export function pageBodyText(blocks = []) {
  return blocks.map(blockText).map(text => text.trim()).filter(Boolean).join('\n');
}

async function retrievePageBodyText(blockId, depth = 0, budget = { remaining: 500 }) {
  if (depth > 4 || budget.remaining <= 0) return '';
  const blocks = await retrieveBlockChildren(blockId);
  const parts = [];
  for (const block of blocks) {
    if (budget.remaining <= 0) break;
    budget.remaining -= 1;
    const text = blockText(block).trim();
    if (text) parts.push(text);
    if (block.has_children && depth < 4) {
      const childText = await retrievePageBodyText(block.id, depth + 1, budget);
      if (childText) parts.push(childText);
    }
  }
  return parts.join('\n');
}

function mentionedUserIds(comments = []) {
  return [...new Set(comments.flatMap(comment => comment.rich_text || [])
    .filter(text => text.type === 'mention' && text.mention?.type === 'user')
    .map(text => text.mention.user?.id)
    .filter(Boolean))];
}

export function extractAnalysisJsonFromBlocks(blocks = []) {
  for (const block of blocks) {
    if (block.type !== 'code') continue;
    const text = blockText(block).trim();
    if (!text.startsWith('{')) continue;
    try {
      const parsed = JSON.parse(text);
      if (parsed?.overall && Array.isArray(parsed.projects)) return text;
    } catch { /* 다른 코드 블록은 무시 */ }
  }
  return null;
}

const summaryTime = row => row['분석 시각']?.start || row['분석 시각'] || row['생성시각'] || row['date:기준일:start'] || row._edited || row._created || '';

function isOverallSummaryRow(row) {
  const name = norm(pick(row, ['프로젝트명', '프로젝트', '이름', 'Name']));
  return /^(전체|전체업무|전체프로젝트|overall|all)(\/|$)/.test(name);
}

function isMachineSummaryRow(row) {
  return String(row.run_id || '').startsWith('rule-input:')
    || String(row.run_id || '').startsWith('dashboard-snapshot:');
}

export async function collectSummaryRows(config, errors = [], since = new Date(Date.now() - 14 * 86400_000).toISOString(), {
  hydrateSummaryBodies = true,
  querySummaryDatabase = queryDatabase,
  retrieveSummaryBlocks = retrieveBlockChildren,
} = {}) {
  const summaryRows = [];
  try {
    const pages = await querySummaryDatabase(config.notion.summaryDbId, { timestamp: 'created_time', created_time: { on_or_after: since } });
    const pageRows = pages.map(page => ({ page, row: flatten(page) }));
    const overall = pageRows
      .filter(({ row }) => !isMachineSummaryRow(row) && isOverallSummaryRow(row))
      .sort((left, right) => String(summaryTime(right.row)).localeCompare(String(summaryTime(left.row))))[0];
    if (hydrateSummaryBodies && overall && !overall.row['분석 결과 JSON']) {
      try { overall.row['분석 결과 JSON'] = extractAnalysisJsonFromBlocks(await retrieveSummaryBlocks(overall.page.id)); }
      catch (error) { errors.push(`업무현황 요약 상세 ${overall.page.id}: ${error.message}`); }
    }
    summaryRows.push(...pageRows.map(({ row }) => row));
  } catch (error) {
    errors.push(`업무현황 요약 DB: ${error.message}`);
  }
  return summaryRows.sort((a, b) => String(summaryTime(b)).localeCompare(String(summaryTime(a))));
}

export function parseProjectRows(rows, config) {
  const sprintOptionalProjects = new Set(config.validation?.sprintOptionalProjects || []);
  return rows.map(row => {
    const name = String(row['이름'] || '').trim();
    const notionSprintRequired = pick(row, ['스프린트 필수', '스프린트 사용']);
    return {
      notionId: row._id,
      name,
      goal: pick(row, ['프로젝트 목표', '목표', 'Goal']) || '',
      scopeFreezePlannedAt: dateStart(pick(row, ['범위 확정 예정일', '범위확정 예정일'])),
      productionCompletePlannedAt: dateStart(pick(row, ['제작 완료 예정일', '제작완료 예정일'])),
      targetAt: dateStart(pick(row, ['최종 목표일', '목표일', '출시일'])),
      channels: list(row['채널명']),
      keywords: row['키워드'] || '',
      meetingUrl: row['회의록 URL'] || '',
      gitUrl: pick(row, ['git', 'Git', 'Git 저장소', '저장소']) || null,
      currentSprints: list(pick(row, ['현재 스프린트', '현재스프린트'])),
      sprintRequired: notionSprintRequired === false
        ? false
        : notionSprintRequired === true
          ? true
          : !sprintOptionalProjects.has(name),
      pdUsers: userList(pick(row, ['PD:users'])),
      teamLeadUsers: userList(pick(row, ['팀장:users'])),
      days: row['조회 기간'] || config.slackDaysDefault,
      historicalContextDays: config.historicalContextDays || 45,
      summarize: row['요약'] !== false,
    };
  }).filter(project => project.name);
}

export function taskFrom(row, titleProject, projectByNotionId, ignoredIds) {
  const dates = pick(row, ['시작날짜 <-> Dead Line', '기간', '날짜']);
  const rawUsers = pick(row, ['담당자:users']) || (pick(row, ['담당자']) || []).map(name => ({ id: name, name }));
  const assignees = removeIgnoredAssignees(rawUsers, ignoredIds);
  const projectProperty = pick(row, ['프로젝트']);
  const relationProject = Array.isArray(projectProperty) ? projectByNotionId.get(projectProperty[0]) : null;
  const propertyProject = typeof projectProperty === 'string' && projectProperty.trim() ? projectProperty : null;
  const explicitProject = relationProject || propertyProject;
  const project = explicitProject || titleProject || null;
  const title = pick(row, ['작업', '이름', 'Name']);
  const status = pick(row, ['Status', '상태']);
  const branches = list(pick(row, ['브랜치', 'Branch', 'Git 브랜치', 'GitHub 브랜치']));
  const description = pick(row, ['작업 내용 설명', '작업 설명', '설명']);
  return {
    id: row._id, url: row._url, created: row._created, edited: row._edited,
    title: title || '(제목 없음)',
    titleMissing: !String(title || '').trim(),
    status: status || null,
    team: single(pick(row, ['팀'])) || '기타',
    assignees: assignees.names,
    assigneeUsers: assignees.users,
    ignoredAssigneeCount: assignees.removedCount,
    priority: pick(row, ['우선순위']) || null,
    project,
    projectMissing: !explicitProject,
    projectSource: explicitProject ? 'property' : titleProject ? 'database-title' : null,
    parentIds: pick(row, ['상위 항목', '부모 항목', 'Parent item']) || [],
    dependencyIds: pick(row, ['선행 작업', '의존 작업', 'Dependencies']) || [],
    dependencyReviewStatus: pick(row, ['의존관계 검토', '관계 검토 상태']) || null,
    core: pick(row, ['핵심 스펙', '핵심']) ?? true,
    start: dates?.start || null,
    due: dates?.end || null,
    completedAt: dateStart(pick(row, ['완료일', '완료 날짜', '완료일자'])),
    sprint: pick(row, ['스프린트', 'Sprint']) || null,
    gitKey: pick(row, ['Git 키', '작업 키', '이슈 키']) || null,
    branch: branches[0] || null,
    branches,
    description: String(description || '').trim(),
    descriptionChecked: description !== null,
    commentMentionUserIds: [],
    commentCheckAvailable: false,
    delayReason: pick(row, ['지연 사유', '일정 변경 사유']) || null,
    previousDue: dateStart(pick(row, ['변경 전 마감일', '기존 마감일'])) || null,
    delayTaggedUsers: pick(row, ['지연 공유 대상:users', '일정 변경 공유 대상:users', 'PD:users']) || [],
  };
}

async function collectWork(allProjects, config, errors, { hydrateBodies = true, checkComments = true } = {}) {
  const workDbs = (await searchDatabases('작업 현황')).filter(database => /작업\s*현황/.test(dbTitle(database)));
  const setup = inspectWorkDatabaseSetup(workDbs.map(database => ({ id: database.id, title: dbTitle(database), properties: database.properties })));
  const ignoredIds = ignoredNotionUserIds(config);
  const projectByNotionId = new Map(allProjects.map(project => [project.notionId, project.name]));
  const tasks = new Map();
  for (const database of workDbs) {
    const title = dbTitle(database);
    let rows = [];
    try { rows = await queryDatabase(database.id); } catch (error) { errors.push(`작업DB ${title}: ${error.message}`); }
    const titleProject = allProjects.find(project => norm(title).includes(norm(project.name)))?.name || null;
    for (const raw of rows) {
      const task = taskFrom(flatten(raw), titleProject, projectByNotionId, ignoredIds);
      tasks.set(task.id, task);
    }
  }
  const hydrated = [];
  const resolvedTasks = resolveTaskProjects([...tasks.values()]);
  const selectedTasks = selectProjectTasks(resolvedTasks, allProjects.filter(project => project.summarize));
  const collectedTasks = excludeUncollectedHierarchy(selectedTasks);
  for (const task of collectedTasks) {
    if (hydrateBodies && !(task.parentIds || []).length) {
      try {
        const body = pageBodyText(await retrieveBlockChildren(task.id));
        task.description = [task.description, body].filter(Boolean).join('\n').trim();
        task.descriptionChecked = true;
      } catch (error) {
        if (!task.descriptionChecked) errors.push(`상위항목 설명 ${task.title}: ${error.message}`);
      }
    }
    if (checkComments && task.status === '확인 요청') {
      try {
        task.commentMentionUserIds = mentionedUserIds(await retrieveComments(task.id));
        task.commentCheckAvailable = true;
      } catch (error) {
        errors.push(`확인 요청 댓글 ${task.title}: ${error.message}`);
      }
    }
    hydrated.push(task);
  }
  return {
    tasks: hydrated,
    notionSetup: setup,
    excludedStatusWorkItems: selectedTasks.length - collectedTasks.length,
  };
}

async function collectMeetings(projects, errors, since, { hydrateMeetingBodies = true, meetingBodyBudget = 500 } = {}) {
  const meetings = [];
  for (const database of await searchDatabases('회의록')) {
    const title = dbTitle(database);
    if (!title.includes('회의록')) continue;
    let rows = [];
    try { rows = await queryDatabase(database.id, { timestamp: 'last_edited_time', last_edited_time: { on_or_after: since } }); }
    catch (error) { errors.push(`회의록DB ${title}: ${error.message}`); }
    const project = projects.find(item => norm(title).includes(norm(item.name)))?.name || title.replace(/회의록/g, '').trim();
    for (const raw of rows) {
      const row = flatten(raw);
      const meetingSummary = String(pick(row, ['요약', 'Summary']) || '').trim();
      let content = meetingSummary;
      let contentChecked = false;
      if (hydrateMeetingBodies) {
        try {
          const body = await retrievePageBodyText(row._id, 0, { remaining: meetingBodyBudget });
          content = [meetingSummary, body].filter(Boolean).join('\n').slice(0, 12_000);
          contentChecked = true;
        } catch (error) {
          errors.push(`회의록 본문 ${row._id}: ${error.message}`);
        }
      }
      meetings.push({
        project,
        title: pick(row, ['회의 주제', '이름', '제목', 'Name']) || '(제목 없음)',
        date: pick(row, ['날짜', '일자', '회의 일자'])?.start || row._created,
        url: row._url,
        content,
        contentChecked,
      });
    }
  }
  return meetings.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
}

export async function collectNotionData(config, errors, options = {}) {
  const allProjects = parseProjectRows((await queryDatabase(config.notion.projectListDbId)).map(flatten), config);
  const projects = allProjects.filter(project => project.summarize);
  const { tasks, notionSetup, excludedStatusWorkItems } = await collectWork(allProjects, config, errors, options);
  const since = new Date(Date.now() - 14 * 86400_000).toISOString();
  const meetings = await collectMeetings(projects, errors, since, options);
  const summaryRows = await collectSummaryRows(config, errors, since, options);
  return {
    projects,
    tasks,
    meetings,
    summaryRows,
    notionSetup,
    collectionStats: { excludedStatusWorkItems },
  };
}

const REQUIRED_PROPERTIES = [
  ['작업', ['작업', '이름', 'Name']],
  ['상태', ['Status', '상태']],
  ['담당자', ['담당자']],
  ['상위 항목', ['상위 항목', '부모 항목', 'Parent item']],
  ['기간', ['시작날짜 <-> Dead Line', '기간', '날짜']],
  ['프로젝트', ['프로젝트']],
  ['스프린트', ['스프린트', 'Sprint']],
  ['우선순위', ['우선순위']],
  ['브랜치', ['브랜치', 'Branch', 'Git 브랜치', 'GitHub 브랜치']],
];

export function inspectWorkDatabaseSetup(databases) {
  const inspected = databases.map(database => {
    const propertyNames = Object.keys(database.properties || {});
    const missingProperties = REQUIRED_PROPERTIES
      .filter(([, aliases]) => !aliases.some(alias => propertyNames.includes(alias)))
      .map(([label]) => label);
    return {
      id: database.id,
      title: database.title,
      propertyNames,
      missingProperties,
      ready: missingProperties.length === 0,
    };
  });
  return {
    ready: inspected.length > 0 && inspected.every(database => database.ready),
    databases: inspected,
  };
}

export function ignoredNotionUserIds(config = {}, env = process.env) {
  const configured = config.ignoredNotionUserIds || [];
  const fromEnvironment = String(env.IGNORED_NOTION_USER_IDS || '')
    .split(',')
    .map(value => value.trim())
    .filter(Boolean);
  return new Set([...configured, ...fromEnvironment]);
}

export function removeIgnoredAssignees(users, ignoredIds) {
  const kept = (users || []).filter(user => !ignoredIds.has(user.id));
  return {
    names: kept.map(user => user.name).filter(Boolean),
    users: kept,
    removedCount: (users || []).length - kept.length,
  };
}

const API = 'https://api.notion.com/v1';
const VERSION = '2022-06-28';
const DEFAULT_REQUEST_TIMEOUT_MS = 20_000;
const MAX_RATE_LIMIT_RETRIES = 3;

async function call(pathname, { method = 'GET', body, rateLimitRetries = 0 } = {}) {
  const controller = new AbortController();
  const timeoutMs = Number(process.env.NOTION_REQUEST_TIMEOUT_MS || DEFAULT_REQUEST_TIMEOUT_MS);
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  let res;
  try {
    res = await fetch(`${API}${pathname}`, {
      method,
      headers: {
        Authorization: `Bearer ${process.env.NOTION_TOKEN}`,
        'Notion-Version': VERSION,
        'Content-Type': 'application/json',
      },
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
  } catch (error) {
    if (error.name === 'AbortError') throw new Error(`Notion 요청 타임아웃(${timeoutMs}ms) ${pathname}`);
    throw error;
  } finally {
    clearTimeout(timeout);
  }
  if (res.status === 429) {
    if (rateLimitRetries >= MAX_RATE_LIMIT_RETRIES) {
      throw new Error(`Notion 요청 제한 초과(${MAX_RATE_LIMIT_RETRIES}회 재시도) ${pathname}`);
    }
    const wait = Math.min(Number(res.headers.get('retry-after') || 1) * 1000, 5_000);
    await new Promise(r => setTimeout(r, wait));
    return call(pathname, { method, body, rateLimitRetries: rateLimitRetries + 1 });
  }
  const json = await res.json();
  if (!res.ok) throw new Error(`Notion ${res.status} ${pathname}: ${json.message || res.statusText}`);
  return json;
}

// 페이지네이션 전체 조회
export async function queryDatabase(dbId, filter, sorts) {
  const rows = [];
  let cursor;
  do {
    const body = { page_size: 100 };
    if (filter) body.filter = filter;
    if (sorts) body.sorts = sorts;
    if (cursor) body.start_cursor = cursor;
    const res = await call(`/databases/${dbId}/query`, { method: 'POST', body });
    rows.push(...res.results);
    cursor = res.has_more ? res.next_cursor : null;
  } while (cursor);
  return rows;
}

export async function searchDatabases(query) {
  const out = [];
  let cursor;
  do {
    const body = { query, filter: { property: 'object', value: 'database' }, page_size: 100 };
    if (cursor) body.start_cursor = cursor;
    const res = await call('/search', { method: 'POST', body });
    out.push(...res.results);
    cursor = res.has_more ? res.next_cursor : null;
  } while (cursor);
  return out;
}

export async function retrieveBlockChildren(blockId) {
  const blocks = [];
  let cursor;
  do {
    const query = new URLSearchParams({ page_size: '100' });
    if (cursor) query.set('start_cursor', cursor);
    const res = await call(`/blocks/${blockId}/children?${query}`);
    blocks.push(...res.results);
    cursor = res.has_more ? res.next_cursor : null;
  } while (cursor);
  return blocks;
}

export async function retrieveComments(blockId) {
  const comments = [];
  let cursor;
  do {
    const query = new URLSearchParams({ block_id: blockId, page_size: '100' });
    if (cursor) query.set('start_cursor', cursor);
    const res = await call(`/comments?${query}`);
    comments.push(...res.results);
    cursor = res.has_more ? res.next_cursor : null;
  } while (cursor);
  return comments;
}

