// Notion 속성 객체 → 평평한 JS 값
export function flatten(page) {
  const out = { _id: page.id, _url: page.url, _created: page.created_time, _edited: page.last_edited_time };
  for (const [name, prop] of Object.entries(page.properties || {})) {
    out[name] = flatProp(prop);
    if (prop.type === 'people') {
      out[`${name}:users`] = (prop.people || []).map(user => ({
        id: user.id,
        name: user.name || null,
      }));
    }
  }
  return out;
}

function richText(arr) {
  return (arr || []).map(t => t.plain_text).join('');
}

function flatProp(p) {
  switch (p.type) {
    case 'title': return richText(p.title);
    case 'rich_text': return richText(p.rich_text);
    case 'select': return p.select?.name ?? null;
    case 'status': return p.status?.name ?? null;
    case 'multi_select': return (p.multi_select || []).map(o => o.name);
    case 'people': return (p.people || []).map(u => u.name || u.id);
    case 'relation': return (p.relation || []).map(page => page.id);
    case 'date': return p.date ? { start: p.date.start, end: p.date.end } : null;
    case 'checkbox': return p.checkbox;
    case 'number': return p.number;
    case 'url': return p.url;
    case 'created_time': return p.created_time;
    case 'formula': return p.formula?.[p.formula?.type] ?? null;
    default: return null;
  }
}

export function dbTitle(db) {
  return richText(db.title).trim();
}

import fs from 'node:fs';
import path from 'node:path';

const KST_OFFSET_MS = 9 * 60 * 60 * 1000;

function kstDay(isoDate) {
  return new Date(new Date(isoDate).getTime() + KST_OFFSET_MS).toISOString().slice(0, 10);
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function sourceStatus(successful, expected, hasError) {
  if (successful === 0 && expected > 0) return 'unavailable';
  if (hasError || successful < expected) return 'partial';
  return 'ok';
}

export function buildSourceHealth(dashboard) {
  const errors = dashboard.errors || [];
  const expectedChannels = unique(dashboard.projects.flatMap(project => project.config?.channels || []));
  const collectedChannels = unique(dashboard.projects.flatMap(project => (project.slack || []).map(channel => channel.channel)));
  const notionErrors = errors.some(error => /Notion|작업DB|업무현황 요약 DB/.test(error));
  const meetingErrors = errors.some(error => /회의록DB/.test(error));
  const slackErrors = errors.some(error => /Slack|SLACK_TOKEN|^#/.test(error));
  const projectCount = dashboard.projects.length;
  const meetingDates = (dashboard.meetings || []).map(meeting => meeting.date).filter(Boolean).sort();
  const agentStatus = dashboard.ai?.analysisStatus || (dashboard.ai?.overall ? 'success' : 'not_run');
  const agentSourceStatus = agentStatus === 'success' ? 'ok'
    : ['partial', 'legacy', 'stale'].includes(agentStatus) ? 'partial'
      : 'unavailable';

  return {
    status: notionErrors || meetingErrors || slackErrors || collectedChannels.length < expectedChannels.length || agentSourceStatus !== 'ok' ? 'limited' : 'complete',
    sources: [
      {
        id: 'notion',
        status: sourceStatus(projectCount > 0 ? 1 : 0, 1, notionErrors),
        successful: projectCount > 0 ? 1 : 0,
        expected: 1,
        lastSuccessAt: projectCount > 0 ? dashboard.generatedAt : null,
      },
      {
        id: 'slack',
        status: sourceStatus(collectedChannels.length, expectedChannels.length, slackErrors),
        successful: collectedChannels.length,
        expected: expectedChannels.length,
        lastSuccessAt: collectedChannels.length > 0 ? dashboard.generatedAt : null,
      },
      {
        id: 'meetings',
        status: sourceStatus(meetingErrors ? 0 : 1, 1, meetingErrors),
        successful: meetingErrors ? 0 : 1,
        expected: 1,
        lastSuccessAt: meetingErrors ? null : dashboard.generatedAt,
        lastEvidenceAt: meetingDates.at(-1) || null,
      },
      {
        id: 'agent-analysis',
        status: agentSourceStatus,
        successful: agentSourceStatus === 'unavailable' ? 0 : 1,
        expected: 1,
        lastSuccessAt: dashboard.ai?.generatedAt || null,
        analysisStatus: agentStatus,
        comparisonStatus: dashboard.ai?.sourceComparison?.status || 'not_run',
      },
    ],
  };
}

export function comparableSnapshot(dashboard) {
  return {
    generatedAt: dashboard.generatedAt,
    projects: dashboard.projects.map(project => ({
      name: project.name,
      status: project.aiStatus || project.notionSummary?.status || null,
      completionRate: project.stats.total > 0 ? Math.round((project.stats.done / project.stats.total) * 100) : 0,
      tasks: [...new Map((project.specs?.length
        ? project.specs.flatMap(spec => spec.tasks || [])
        : project.activeTasks || []).map(task => [task.id || task.title, task])).values()].map(task => ({
        id: task.id || task.title,
        title: task.title,
        status: task.status || null,
        due: task.due || null,
        assignees: [...(task.assignees || [])].sort(),
      })).sort((left, right) => left.id.localeCompare(right.id)),
    })).sort((left, right) => left.name.localeCompare(right.name)),
  };
}

function addDelta(deltas, project, field, from, to, task = null) {
  if (JSON.stringify(from) === JSON.stringify(to)) return;
  deltas.push({
    id: `${project}:${task?.id || 'project'}:${field}`,
    project,
    taskId: task?.id || null,
    taskTitle: task?.title || null,
    field,
    from,
    to,
  });
}

export function diffSnapshots(previous, current) {
  const deltas = [];
  const previousProjects = new Map(previous.projects.map(project => [project.name, project]));
  for (const project of current.projects) {
    const before = previousProjects.get(project.name);
    if (!before) continue;
    addDelta(deltas, project.name, 'project.status', before.status, project.status);
    addDelta(deltas, project.name, 'project.completionRate', before.completionRate, project.completionRate);
    const previousTasks = new Map(before.tasks.map(task => [task.id, task]));
    for (const task of project.tasks) {
      const priorTask = previousTasks.get(task.id);
      if (!priorTask) continue;
      addDelta(deltas, project.name, 'task.status', priorTask.status, task.status, task);
      addDelta(deltas, project.name, 'task.due', priorTask.due, task.due, task);
      addDelta(deltas, project.name, 'task.assignees', priorTask.assignees, task.assignees, task);
    }
  }
  return deltas;
}

export function loadPreviousSnapshot(dataDirectory, currentDay) {
  const snapshotDirectory = path.join(dataDirectory, 'snapshots');
  if (!fs.existsSync(snapshotDirectory)) return null;
  const previousFile = fs.readdirSync(snapshotDirectory)
    .filter(file => /^\d{4}-\d{2}-\d{2}\.json$/.test(file) && file.slice(0, 10) < currentDay)
    .sort()
    .at(-1);
  if (!previousFile) return null;
  return JSON.parse(fs.readFileSync(path.join(snapshotDirectory, previousFile), 'utf8'));
}

export function attachOperationalMetadata(dashboard, dataDirectory, suppliedPrevious = undefined) {
  const current = comparableSnapshot(dashboard);
  const previous = suppliedPrevious === undefined
    ? loadPreviousSnapshot(dataDirectory, kstDay(dashboard.generatedAt))
    : suppliedPrevious;
  return {
    ...dashboard,
    sourceHealth: buildSourceHealth(dashboard),
    snapshotComparison: previous ? {
      available: true,
      previousGeneratedAt: previous.generatedAt,
      currentGeneratedAt: current.generatedAt,
      reason: null,
    } : {
      available: false,
      previousGeneratedAt: null,
      currentGeneratedAt: current.generatedAt,
      reason: '전일 스냅샷이 없어 변화 비교를 생성하지 않았습니다.',
    },
    deltas: previous ? diffSnapshots(previous, current) : [],
  };
}

export function saveDailySnapshot(dashboard, dataDirectory) {
  const snapshotDirectory = path.join(dataDirectory, 'snapshots');
  fs.mkdirSync(snapshotDirectory, { recursive: true });
  const file = path.join(snapshotDirectory, `${kstDay(dashboard.generatedAt)}.json`);
  fs.writeFileSync(file, JSON.stringify(comparableSnapshot(dashboard), null, 2));
  return file;
}

import { classifyExecutionAttention } from './execution-attention.mjs';

const PATTERNS = Object.freeze({
  release: /(배포|릴리즈|출시|서밋|스토어|마켓\s*업로드|자동\s*출시|롤아웃|release|submit)/i,
  qa: /(qa|fun\s*qa|funqa|디렉터\s*리뷰|품질\s*검증)/i,
  build: /(빌드|apk|aab|testflight|aos|ios|빌드버전|빌드코드|build)/i,
  data: /(데이터|지표|cpi|리텐션|retention|퍼널|funnel|d1|d7|roas|ltv|arpu|분석|tracking\s*plan|통계)/i,
});

const CATEGORY_LABELS = Object.freeze({ build: '빌드', qa: 'QA/리뷰', release: '배포/출시', data: '데이터' });

function stripSlack(value) {
  return String(value || '')
    .replace(/<https?:\/\/[^>|]+\|([^>]+)>/g, '$1')
    .replace(/<https?:\/\/[^>]+>/g, '')
    .replace(/<@[^>]+>/g, '담당자')
    .replace(/<![^>|]+\|([^>]+)>/g, '$1')
    .replace(/[*_~`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function excerpt(value, limit = 280) {
  const text = stripSlack(value);
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text;
}

function categoriesFor(text) {
  return Object.entries(PATTERNS).filter(([, pattern]) => pattern.test(text)).map(([category]) => category);
}

function eventKey(event) { return event.url || `${event.timestamp || ''}|${event.channel || ''}|${event.excerpt}`; }
function latest(events, category) { return events.find(event => event.categories.includes(category)) || null; }

function evidenceFromEvent(event) {
  if (!event) return null;
  return {
    source: 'slack', evidenceRole: 'project_operation', timestamp: event.timestamp,
    title: `#${event.channel} · ${event.categories.map(category => CATEGORY_LABELS[category]).join(' · ')}`,
    excerpt: event.excerpt, url: event.url,
    attention: event.attention, attentionType: event.attentionType, attentionAction: event.attentionAction,
  };
}

export function buildProjectOperations(slackChannels = []) {
  const collected = [];
  for (const channel of slackChannels || []) {
    for (const message of channel.messages || []) {
      const text = stripSlack([message.parentText || '', message.text || ''].filter(Boolean).join(' · '));
      if (!text) continue;
      const categories = categoriesFor(text);
      if (!categories.length) continue;
      const attention = classifyExecutionAttention(text);
      collected.push({
        timestamp: message.time || null, channel: channel.channel || 'unknown', url: message.url || null,
        excerpt: excerpt(text), categories,
        attention: Boolean(attention), attentionType: attention?.type || null, attentionAction: attention?.action || null,
      });
    }
  }

  const deduped = new Map();
  for (const event of collected.sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))) {
    const key = eventKey(event);
    if (!deduped.has(key)) deduped.set(key, event);
  }
  const events = [...deduped.values()]
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .slice(0, 12);

  const latestBuild = latest(events, 'build');
  const latestQa = latest(events, 'qa');
  const latestRelease = latest(events, 'release');
  const latestData = latest(events, 'data');
  const lifecycle = [latestBuild, latestQa, latestRelease].filter(Boolean)
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))[0] || null;
  const evidence = [latestBuild, latestQa, latestRelease, latestData]
    .filter(Boolean)
    .filter((event, index, rows) => rows.findIndex(candidate => eventKey(candidate) === eventKey(event)) === index)
    .sort((left, right) => String(right.timestamp || '').localeCompare(String(left.timestamp || '')))
    .map(evidenceFromEvent);

  return {
    latestLifecycleSignal: lifecycle ? {
      category: lifecycle.categories.includes('release') ? 'release' : lifecycle.categories.includes('qa') ? 'qa' : 'build',
      timestamp: lifecycle.timestamp, channel: lifecycle.channel, excerpt: lifecycle.excerpt, url: lifecycle.url,
    } : null,
    latestBuild, latestQa, latestRelease, latestData, events, evidence,
    source: 'slack', evidenceCount: events.length,
  };
}

import { enrichValidationIssue } from './issue-catalog.mjs';

const CLOSED_PARENT = new Set(['완료', '일시 정지', '정지', '중단']);

export function enrichParentChildCompletion(validation, tasks = [], detectedAt = new Date().toISOString()) {
  const childrenByParent = new Map();
  for (const task of tasks.filter(item => (item.parentIds || []).length > 0)) {
    for (const parentId of task.parentIds || []) {
      const rows = childrenByParent.get(parentId) || [];
      rows.push(task);
      childrenByParent.set(parentId, rows);
    }
  }
  const existing = new Set((validation.issues || []).map(issue => `${issue.type}:${issue.specId || ''}`));
  for (const parent of tasks.filter(item => !(item.parentIds || []).length && !CLOSED_PARENT.has(item.status))) {
    const children = childrenByParent.get(parent.id) || [];
    if (!children.length || !children.every(child => child.status === '완료')) continue;
    const key = `PARENT_CHILD_STATUS_MISMATCH:${parent.id}`;
    if (existing.has(key)) continue;
    const issue = enrichValidationIssue({
      id: key,
      type: 'PARENT_CHILD_STATUS_MISMATCH',
      severity: 'check',
      message: `상위 작업은 ${parent.status || '상태 미정'}이지만 등록된 하위 작업항목 ${children.length}건이 모두 완료 상태`,
      project: parent.project || null,
      specId: parent.id,
      workItemId: null,
      detectedAt,
      recommendedAction: '상위 작업을 완료 처리할지, 추가 하위 작업항목이 누락됐는지 확인하세요.',
      metadata: { rule: 'parent-child-completion', parentStatus: parent.status || null, childCount: children.length, completedChildCount: children.length },
    });
    validation.issues.push(issue);
    const ruleItem = (validation.ruleItems || []).find(item => item.id === parent.id);
    if (ruleItem) {
      ruleItem.issues = [...(ruleItem.issues || []), issue];
      ruleItem.riskScore = (ruleItem.riskScore || 0) + 10;
      if (!['error', 'warning'].includes(ruleItem.guideStatus)) ruleItem.guideStatus = 'check';
    }
    existing.add(key);
  }
  return validation;
}

export function zonedClock(now = new Date(), timeZone = 'Asia/Seoul') {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(now);
  const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return { day: `${values.year}-${values.month}-${values.day}`, time: `${values.hour}:${values.minute}` };
}

export function shouldRunDaily({ now = new Date(), timeZone = 'Asia/Seoul', scheduleTime, lastRunDay }) {
  const clock = zonedClock(now, timeZone);
  return { ...clock, shouldRun: clock.time >= scheduleTime && clock.day !== lastRunDay };
}
